424	 * Core logic for submitting team picker selections and assigning players to teams.
425	 *
426	 * This function performs the following operations:
427	 * 1. Validates that at least two players are selected
428	 * 2. Retrieves the current game day and player outcomes
429	 * 3. Clears existing team assignments for all eligible players
430	 * 4. Validates selected players have 'Yes' responses
431	 * 5. Calculates player statistics (average performance, age, position)
432	 * 6. Determines optimal team split based on player averages
433	 * 7. Assigns players to teams and persists assignments
434	 * 8. Sends email notification to all active players with team assignments
435	 *
436	 * @param data - Array of picker inputs containing player selections and metadata
437	 * @param deps - Service dependencies for game day, outcomes, email, and configuration (defaults provided)
438	 * @returns Promise that resolves when team assignments are complete and notifications sent
439	 * @throws {ValidationError} If fewer than two players are selected.
440	 * @throws {NotFoundError} If no current game day is available.
441	 * @throws {ValidationError} If a selected player is not available for the game day.
442	 * @throws {ValidationError} If a selected player has not confirmed participation with 'Yes'.
443	 */
444	export async function coreSubmitPicker(
445	    data: SubmitPickerInput,
446	    deps: SubmitPickerDeps = defaultDeps,
447	): Promise<void> {
448	    const selectedPlayerIds = Array.from(
449	        new Set(data.map((item) => item.playerId)),
450	    );
451	    if (selectedPlayerIds.length < 2) {
452	        throw new ValidationError(
453	            'At least two players are required to pick teams.',
454	        );
455	    }
456	
457	    const gameDay = await deps.gameDayService.getCurrent();
458	    if (!gameDay) {
459	        throw new NotFoundError(
460	            'No current game day available for picking teams.',
461	        );
